package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RegisteredEmailVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property registered email of tenant config ")
  void test_registered_email_v_o_builder() {
    Assertions.assertFalse(RegisteredEmailVO.nullValue().getRegisteredEmail().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(RegisteredEmailVO.tryFrom(null).getRegisteredEmail().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", RegisteredEmailVO.from("one").getRegisteredEmail().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> RegisteredEmailVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", RegisteredEmailVO.from("one").toString());
  }
}
